psutil is not installed — conflicts are still reported, just without the
owning PID.
"""
from __future__ import annotations
import socket
try:
    import psutil as _psutil
except ImportError:
    _psutil = None
DEFAULT_PORTS: dict[str, int] = {'backend': 8012, 'frontend': 5174}

def _get_pid_for_port(port: int) -> int | None:
    """Return the PID of the process listening on *port*, or None."""
    if _psutil is None:
        return None
    _psutil_errors: tuple[type[Exception], ...] = (PermissionError, AttributeError)
    if _psutil is not None:
