    @property
    def parameters(self) -> dict[str, Any]:
        """Return the JSON-schema parameter definition."""
        return {'text': {'type': 'string', 'description': 'Text to trim', 'required': True}, 'max_tokens': {'type': 'integer', 'description': 'Target maximum tokens', 'required': True}, 'head_tokens': {'type': 'integer', 'description': 'Tokens to preserve from the start (default 256)', 'required': False}, 'tail_tokens': {'type': 'integer', 'description': 'Tokens to preserve from the end (default: max_tokens - head_tokens)', 'required': False}, 'marker': {'type': 'string', 'description': 'Marker inserted between head and tail', 'required': False}}

