            tail = text[-tail_chars:] if tail_chars > 0 else ''
            truncated_chars = max(0, len(text) - (len(head) + len(tail)))
            out = head + marker + tail
            return ToolResult(success=True, data={'text': out, 'trimmed': True, 'truncated_chars': truncated_chars, 'estimated_tokens': _estimate_tokens(out), 'max_tokens': max_tokens, 'head_tokens': head_tokens, 'tail_tokens': tail_tokens})
        except Exception as e:
            return ToolResult(success=False, error=str(e))

